package com.tripmateai.service.impl; import com.tripmateai.dto.request.expense.*; import com.tripmateai.dto.response.expense.*; import com.tripmateai.entity.*; import com.tripmateai.exception.*; import com.tripmateai.mapper.ExpenseMapper; import com.tripmateai.repository.*; import com.tripmateai.security.UserPrincipal; import com.tripmateai.service.ExpenseService; import lombok.RequiredArgsConstructor; import org.springframework.data.domain.*; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.math.*; import java.util.*; import java.util.stream.*;
@Service @RequiredArgsConstructor @Transactional public class ExpenseServiceImpl implements ExpenseService {private final ExpenseRepository expenses;private final TripRepository trips;private final ExpenseCategoryRepository categories;private User user(){var p=SecurityContextHolder.getContext().getAuthentication().getPrincipal();if(!(p instanceof UserPrincipal u))throw new UnauthorizedException("Authentication required");return u.user();} private Trip trip(Long id){return trips.findByIdAndUser(id,user()).orElseThrow(()->trips.existsById(id)?new UnauthorizedException("You do not have access to this trip"):new ResourceNotFoundException("Trip not found"));} private Expense expense(Long tripId,Long id){return expenses.findByIdAndTrip(id,trip(tripId)).orElseThrow(()->new ResourceNotFoundException("Expense not found"));} private ExpenseCategory category(Long id){if(id==null)return null;var c=categories.findById(id).orElseThrow(()->new ResourceNotFoundException("Expense category not found"));if(c.getUser()!=null&&!c.getUser().getId().equals(user().getId()))throw new UnauthorizedException("You do not have access to this expense category");return c;} private Pageable page(int p,int s){return PageRequest.of(Math.max(0,p),Math.min(Math.max(1,s),100),Sort.by(Sort.Direction.DESC,"expenseDate"));} public ExpenseResponse create(Long id,ExpenseRequest r){if(!id.equals(r.tripId()))throw new BadRequestException("Trip ID must match path");var e=new Expense();e.setTrip(trip(id));e.setUser(user());e.setTitle(r.title());e.setAmount(r.amount());e.setExpenseDate(r.expenseDate());e.setCategory(category(r.categoryId()));return ExpenseMapper.toResponse(expenses.save(e));} @Transactional(readOnly=true) public Page<ExpenseResponse> list(Long id,int p,int s){return expenses.findByTrip(trip(id),page(p,s)).map(ExpenseMapper::toResponse);} @Transactional(readOnly=true) public ExpenseResponse get(Long t,Long id){return ExpenseMapper.toResponse(expense(t,id));} public ExpenseResponse update(Long t,Long id,UpdateExpenseRequest r){var e=expense(t,id);e.setTitle(r.title());e.setAmount(r.amount());e.setExpenseDate(r.expenseDate());e.setCategory(category(r.categoryId()));return ExpenseMapper.toResponse(expenses.save(e));} public void delete(Long t,Long id){expenses.delete(expense(t,id));} @Transactional(readOnly=true) public ExpenseSummaryResponse summary(Long id){var all=expenses.findByTrip(trip(id));var total=all.stream().map(Expense::getAmount).reduce(BigDecimal.ZERO,BigDecimal::add);var groups=all.stream().collect(Collectors.groupingBy(e->e.getCategory()==null?"UNCATEGORIZED":e.getCategory().getName(),LinkedHashMap::new,Collectors.reducing(BigDecimal.ZERO,Expense::getAmount,BigDecimal::add)));return new ExpenseSummaryResponse(total,null,all.size(),groups);}}
